from collections import deque

def comps(grid):
 h,w=len(grid),len(grid[0]); seen=set(); out=[]
 for r in range(h):
  for c in range(w):
   color=grid[r][c]
   if color and (r,c) not in seen:
    q=[(r,c)]; seen.add((r,c)); cells=[]
    while q:
     x,y=q.pop(); cells.append((x,y))
     for z in [(x-1,y),(x+1,y),(x,y-1),(x,y+1)]:
      a,b=z
      if 0<=a<h and 0<=b<w and grid[a][b]==color and z not in seen: seen.add(z); q.append(z)
    out.append((color,cells))
 return out

def fall_right(grid):
 h,w=len(grid),len(grid[0]); objs=comps(grid)
 # order rightmost then maybe rows
 objs.sort(key=lambda x:max(c for r,c in x[1]), reverse=True)
 occ={cell:color for color,cells in objs for cell in cells}
 new=[]
 for color,cells in objs:
  for p in cells: occ.pop(p)
  shift=0
  while all(c+shift+1<w and ((r,c+shift+1) not in occ) for r,c in cells): shift+=1
  moved=[(r,c+shift) for r,c in cells]
  for p in moved: occ[p]=color
  new.append((color,moved))
 out=[[0]*w for _ in range(h)]
 for color,cells in new:
  for r,c in cells: out[r][c]=color
 return out

